import * as THREE from 'three';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';

import { Reflector } from 'three/examples/jsm/objects/Reflector.js';

export const getDirectionalLight = (x: number = 100, y: number = 100, z: number = 100) => {
	const light = new THREE.DirectionalLight(0xffffff, 5);
	light.position.set(x, y, z);
	light.castShadow = true;
	light.shadow.bias = -0.00001;
	light.shadow.mapSize.width = 2048 * 4;
	light.shadow.mapSize.height = 2048 * 4;
	light.shadow.camera.near = 0.5;
	light.shadow.camera.far = 1000;
	light.shadow.camera.left = -150;
	light.shadow.camera.right = 150;
	light.shadow.camera.top = 150;
	light.shadow.camera.bottom = -150;
	return light;
};

export const createStudioEnvironment = () => {
	const geometry = new THREE.SphereGeometry(1000, 32, 16);
	const material = new THREE.ShaderMaterial({
		uniforms: {
			topColor: { value: new THREE.Color(0xffffff) },
			bottomColor: { value: new THREE.Color(0xf7f7f7) },
			offset: { value: 1.4 },
			exponent: { value: 1.4 },
		},
		vertexShader: `
      varying vec3 vWorldPosition;
      void main() {
          vec4 worldPosition = modelMatrix * vec4(position, 1.0);
          vWorldPosition = worldPosition.xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
      `,
		fragmentShader: `
      uniform vec3 topColor;
      uniform vec3 bottomColor;
      uniform float offset;
      uniform float exponent;
      varying vec3 vWorldPosition;
      void main() {
          float h = normalize(vWorldPosition + offset).y;
          gl_FragColor = vec4(mix(bottomColor, topColor, max(pow(max(h, 0.0), exponent), 0.0)), 1.0);
      }
      `,
		side: THREE.BackSide,
	});
	return new THREE.Mesh(geometry, material);
};

export const getGroundBasic = (ground: number = 0, zUp = false) => {
	const planeGeometry = new THREE.PlaneGeometry(1500, 1500);
	const planeMaterial = new THREE.MeshStandardMaterial({
		color: 0xededed,
		// color: 0xcecece,
		// color: 0xb4a4a4,
		// roughness: 0.0,
		// metalness: 0.8,
	});

	const planeGround = new THREE.Mesh(planeGeometry, planeMaterial);
	planeGround.receiveShadow = true;
	if (zUp) {
		planeGround.position.z = ground;
	} else {
		planeGround.position.y = ground;
		planeGround.rotation.x = -Math.PI * 0.5;
	}
	planeGround.name = 'ground';
	return planeGround;
};

export const getGround = (scene, renderer) => {
	const groundReflector = new Reflector(new THREE.PlaneGeometry(500, 500), {
		clipBias: 0.03,
		textureWidth: window.innerWidth * window.devicePixelRatio,
		textureHeight: window.innerHeight * window.devicePixelRatio,
		color: 0xcecece,
	});
	// groundReflector.rotation.x = -Math.PI / 2;
	groundReflector.position.z = -18;
	return groundReflector;
};

export const loadFBX = (pathFile: string, scale: number = 1, zUp = false): Promise<THREE.Group> => {
	const scaleFactor = scale;
	const loader = new FBXLoader();

	return new Promise((resolve, reject) => {
		loader.load(
			pathFile,
			(fbx) => {
				fbx.castShadow = true;
				fbx.receiveShadow = true;

				if (zUp) {
					fbx.rotation.x = Math.PI / 2;
				}

				fbx.traverse((child) => {
					if (child.isMesh) {
						child.castShadow = true;
						child.receiveShadow = true;

						const material = child.material;

						if (Array.isArray(material)) {
							child.material = material.map(
								(mat) =>
									// new THREE.MeshStandardMaterial({
									new THREE.MeshPhysicalMaterial({
										map: mat.map ?? null,
										color: mat.color ?? new THREE.Color(0xffffff),
										normalMap: mat.normalMap ?? null,
										roughness: 0.7,
										metalness: 0.1,
									})
							);
						} else {
							child.material = new THREE.MeshPhysicalMaterial({
								map: material.map ?? null,
								color: material.color ?? new THREE.Color(0xffffff),
								// color:  new THREE.Color(0x444444), // material.color ?? new THREE.Color(0xffffff),
								normalMap: material.normalMap ?? null,
								roughness: 0.6,
								metalness: 0.2,
							});
						}
					}
				});

				fbx.scale.set(scaleFactor, scaleFactor, scaleFactor);
				resolve(fbx);
			},
			undefined,
			(error) => {
				reject(error);
			}
		);
	});
};

export const getSlider = (title: string, min: number, max: number) => {
	const div = document.createElement('div');
	div.style.display = 'flex';
	div.style.flexDirection = 'column';
	div.style.alignItems = 'flex-start';
	div.style.gap = '4px';

	const text = document.createElement('div');
	text.textContent = title;
	text.style.color = '#333';
	text.style.fontSize = '12px';

	const slider = document.createElement('input');
	slider.type = 'range';
	slider.min = `${min}`;
	slider.max = `${max}`;

	// 슬라이더 스타일 최소화
	slider.style.width = '150px';
	slider.style.height = '4px';
	slider.style.background = 'transparent';
	slider.style.border = 'none';
	slider.style.outline = 'none';
	slider.style.margin = '0';
	slider.style.padding = '0';
	slider.style.webkitAppearance = 'none';
	slider.style.appearance = 'none';
	slider.style.cursor = 'pointer';

	// 슬라이더 트랙
	slider.style.setProperty('--track-color', '#aaa');

	// 트랙과 썸 스타일을 직접 설정
	const style = document.createElement('style');
	style.textContent = `
	input[type=range]::-webkit-slider-runnable-track {
		height: 4px;
		background: #aaa;
		border-radius: 2px;
	}
	input[type=range]::-webkit-slider-thumb {
		-webkit-appearance: none;
		height: 10px;
		width: 10px;
		border-radius: 50%;
		background: #333;
		margin-top: -3px;
	}
	input[type=range]::-moz-range-track {
		height: 4px;
		background: #333;
		border-radius: 2px;
	}
	input[type=range]::-moz-range-thumb {
		height: 10px;
		width: 10px;
		border-radius: 50%;
		background: #333;
	}
	`;
	document.head.appendChild(style);

	div.appendChild(text);
	div.appendChild(slider);

	return {
		div,
		slider,
		text,
	};
};

export const getCheckBox = (title: string) => {
	const div = document.createElement('div');
	div.style.display = 'flex';

	const checkBox = document.createElement('input');
	checkBox.type = 'checkbox';
	checkBox.defaultChecked = false;
	const text = document.createElement('div');
	text.textContent = title;
	text.style.fontSize = '12px';
	text.style.color = '#333';
	div.appendChild(checkBox);
	div.appendChild(text);

	return {
		div,
		checkBox,
	};
};
export const getDeepCloneGroup = (original: THREE.Group): THREE.Group => {
	const clone = original.clone(true);
	clone.traverse((child) => {
		if ((child as THREE.Mesh).isMesh) {
			const mesh = child as THREE.Mesh;
			mesh.geometry = mesh.geometry.clone();

			if (Array.isArray(mesh.material)) {
				mesh.material = mesh.material.map((mat) => mat.clone());
			} else {
				mesh.material = mesh.material.clone();
			}
		}
	});
	return clone;
};
